import { useMemo, useState } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from mareysTrains ----
type Station_mareysTrains = { name: string; distance: number };
type ServiceType = 'local' | 'limited' | 'bullet';
type Stop_mareysTrains = { station: Station_mareysTrains; time: Date };
type Train = {
  id: string;
  number: number;
  type: ServiceType;
  direction: 'N' | 'S';
  stops: Stop_mareysTrains[];
};

// Peninsula corridor stations, distance in miles from the northern terminal.
const stations: Station_mareysTrains[] = [
  { name: 'San Francisco', distance: 0 },
  { name: '22nd Street', distance: 1.5 },
  { name: 'Bayshore', distance: 5.0 },
  { name: 'South San Francisco', distance: 8.9 },
  { name: 'San Bruno', distance: 11.1 },
  { name: 'Millbrae', distance: 13.7 },
  { name: 'Broadway', distance: 15.4 },
  { name: 'Burlingame', distance: 16.4 },
  { name: 'San Mateo', distance: 17.8 },
  { name: 'Hayward Park', distance: 18.7 },
  { name: 'Hillsdale', distance: 20.1 },
  { name: 'Belmont', distance: 21.6 },
  { name: 'San Carlos', distance: 23.0 },
  { name: 'Redwood City', distance: 25.7 },
  { name: 'Atherton', distance: 27.3 },
  { name: 'Menlo Park', distance: 28.7 },
  { name: 'Palo Alto', distance: 30.1 },
  { name: 'California Ave', distance: 31.6 },
  { name: 'San Antonio', distance: 33.9 },
  { name: 'Mountain View', distance: 35.7 },
  { name: 'Sunnyvale', distance: 38.5 },
  { name: 'Lawrence', distance: 41.0 },
  { name: 'Santa Clara', distance: 44.5 },
  { name: 'College Park', distance: 45.5 },
  { name: 'San Jose Diridon', distance: 47.5 },
  { name: 'Tamien', distance: 49.5 }
];

const PATTERN: Record<ServiceType, number[]> = {
  local: stations.map((_, i) => i),
  limited: [0, 1, 3, 5, 8, 10, 12, 13, 15, 16, 19, 20, 22, 24, 25],
  bullet: [0, 5, 13, 16, 19, 24, 25]
};

const CRUISE_MPH: Record<ServiceType, number> = { local: 42, limited: 48, bullet: 55 };
const DWELL_MIN = 0.8;

// Bullets leave 12 minutes behind an hourly local, which is what makes the overtakes visible.
const SCHEDULE: Record<ServiceType, { hours: number[]; minute: number }> = {
  local: { hours: [5, 6, 7, 8, 9, 11, 13, 15, 16, 17, 18, 19, 21], minute: 0 },
  limited: { hours: [6, 7, 8, 10, 12, 14, 16, 17, 18, 20], minute: 35 },
  bullet: { hours: [7, 8, 16, 17, 18], minute: 12 }
};

const SERVICE_DAY = Date.UTC(2024, 4, 6);

function runTrain(
  number: number,
  type: ServiceType,
  direction: 'N' | 'S',
  departMinute: number
): Train {
  const order = direction === 'S' ? PATTERN[type] : [...PATTERN[type]].reverse();
  let minute = departMinute;
  const stops = order.map((index, k) => {
    const station = stations[index];
    if (k > 0) {
      const previous = stations[order[k - 1]];
      const miles = Math.abs(station.distance - previous.distance);
      minute += (miles / CRUISE_MPH[type]) * 60 + DWELL_MIN;
    }
    return { station, time: new Date(SERVICE_DAY + minute * 60000) };
  });
  return { id: `${number}${direction}`, number, type, direction, stops };
}

function timetable(direction: 'N' | 'S'): Train[] {
  const departures = (Object.keys(SCHEDULE) as ServiceType[]).flatMap((type) =>
    SCHEDULE[type].hours.map((hour) => ({ type, minute: hour * 60 + SCHEDULE[type].minute }))
  );
  departures.sort((a, b) => a.minute - b.minute);
  const first = direction === 'S' ? 101 : 102;
  return departures.map((d, i) => runTrain(first + i * 2, d.type, direction, d.minute));
}

const trains: Train[] = [...timetable('S'), ...timetable('N')];

type Station = { name: string; distance: number };
type Stop = { station: Station; time: Date };

/**
 * The stops of the line, at their true distance along it, and every run through them.
 * A run's stops must be in travel order; its `station` values come from `stations`.
 */
export type Data = {
  stations: Station[];
  trains: {
    id: string;
    number: number;
    type: ServiceType;
    direction: 'N' | 'S';
    stops: Stop[];
  }[];
};

const DEMO: Data = { stations, trains };

const MARGIN = { top: 40, right: 26, bottom: 34, left: 122 };
const LABEL_GAP = 12;

const DIRECTION_COLOR: Record<'N' | 'S', string> = { N: '#4269d0', S: '#efb118' };

const SERVICE: Record<ServiceType, { label: string; strokeWidth: number; dash?: string }> = {
  local: { label: 'Local', strokeWidth: 1, dash: '3,2' },
  limited: { label: 'Limited', strokeWidth: 1.5 },
  bullet: { label: 'Baby bullet', strokeWidth: 2.4 }
};

const LEGEND = [
  { label: 'Northbound', color: DIRECTION_COLOR.N, strokeWidth: 2, dash: undefined },
  { label: 'Southbound', color: DIRECTION_COLOR.S, strokeWidth: 2, dash: undefined },
  ...(Object.keys(SERVICE) as ServiceType[]).map((type) => ({
    label: SERVICE[type].label,
    color: 'var(--muted)',
    strokeWidth: SERVICE[type].strokeWidth,
    dash: SERVICE[type].dash
  }))
];

export default function MareysTrains({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.max(560, Math.round(width * 0.8));
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const [hovered, setHovered] = useState<string | null>(null);

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain(d3.extent(data.trains.flatMap((t) => t.stops), (s) => s.time) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  // Stations sit at their true distance along the line, so a line's slope is its speed.
  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data.stations, (s) => s.distance) ?? 0])
        .range([0, innerHeight]),
    [data, innerHeight]
  );

  const runs = useMemo(() => {
    const line = d3
      .line<Stop>()
      .x((s) => x(s.time))
      .y((s) => y(s.station.distance));
    return data.trains.map((t) => ({ ...t, path: line(t.stops) ?? '' }));
  }, [data, x, y]);

  const rows: Tick[] = useMemo(
    () => data.stations.map((s) => ({ value: s.name, offset: y(s.distance) })),
    [data, y]
  );

  const stationTicks: Tick[] = useMemo(() => {
    let last = -Infinity;
    return rows.filter((r) => {
      if (r.offset - last < LABEL_GAP) return false;
      last = r.offset;
      return true;
    });
  }, [rows]);

  const xTicks: Tick[] = useMemo(
    () =>
      x.ticks(Math.max(3, Math.round(innerWidth / 90))).map((v) => ({
        value: d3.utcFormat('%-I %p')(v),
        offset: x(v)
      })),
    [x, innerWidth]
  );

  const perRow = Math.max(2, Math.floor(innerWidth / 112));
  const focus = runs.find((t) => t.id === hovered) ?? null;
  const labelled = useMemo(() => new Set(stationTicks.map((t) => t.value)), [stationTicks]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Marey stringline chart of a commuter rail timetable: time across, stations down by distance"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {rows.map((r) =>
            labelled.has(r.value) ? null : (
              <line key={r.value} className="grid" x1={0} x2={innerWidth} y1={r.offset} y2={r.offset} />
            )
          )}
        </g>
        <AxisLeft ticks={stationTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />

        <g transform={`translate(0,${perRow < LEGEND.length ? -30 : -22})`}>
          {LEGEND.map((item, i) => (
            <g
              key={item.label}
              transform={`translate(${(i % perRow) * 112},${Math.floor(i / perRow) * 16})`}
            >
              <line
                x1={0}
                x2={20}
                y1={0}
                y2={0}
                stroke={item.color}
                strokeWidth={item.strokeWidth}
                strokeDasharray={item.dash}
              />
              <text x={26} dy="0.32em" fill="var(--muted)" fontSize={11}>
                {item.label}
              </text>
            </g>
          ))}
        </g>

        {runs.map((t) => (
          <path
            key={t.id}
            d={t.path}
            fill="none"
            stroke={DIRECTION_COLOR[t.direction]}
            strokeWidth={SERVICE[t.type].strokeWidth}
            strokeDasharray={SERVICE[t.type].dash}
            strokeOpacity={focus && focus.id !== t.id ? 0.15 : 0.85}
            strokeLinejoin="round"
          />
        ))}

        {runs.map((t) => (
          <path
            key={`hit-${t.id}`}
            d={t.path}
            fill="none"
            stroke="transparent"
            strokeWidth={8}
            pointerEvents="stroke"
            onMouseEnter={() => setHovered(t.id)}
            onMouseLeave={() => setHovered(null)}
          />
        ))}

        {focus && (
          <g pointerEvents="none">
            {focus.stops.map((s) => (
              <circle
                key={s.station.name}
                cx={x(s.time)}
                cy={y(s.station.distance)}
                r={2.5}
                fill={DIRECTION_COLOR[focus.direction]}
                stroke="var(--panel)"
              />
            ))}
            <text
              x={Math.min(x(focus.stops[0].time) + 8, innerWidth - 130)}
              y={y(focus.stops[0].station.distance) - 8}
              fill="var(--text)"
              fontSize={12}
            >
              {`${focus.number}${focus.direction} · ${SERVICE[focus.type].label} · ${d3.utcFormat('%-I:%M %p')(focus.stops[0].time)}`}
            </text>
          </g>
        )}
      </g>
    </svg>
  );
}
